 def test_actual_character_logical_icon_field_and_script_override(self):
  char=(ROOT/'source/Character.hx').read_text()
  start=char.index('function get_healthIcon(')
  methods=char[start:char.index(';',start)+1]+'\n'+method(char,'function set_healthIcon(')
  files=source_icon_fixture_files()
  files['PsychFlxCameraCompat.hx']='class PsychFlxCameraCompat {public function getField(f:String):Dynamic return null;public function setField(f:String,v:Dynamic):Dynamic return v;}class PsychFlxGCompat {public static function getField(f:String):Dynamic return null;public static function setField(f:String,v:Dynamic):Dynamic return v;}'
  files['NightmareVisionPlayableSongOwner.hx']='interface NightmareVisionPlayableSongOwner {public function nightmareVisionAudioView():Dynamic;}'
  files['NightmareVisionFlxGView.hx']='class NightmareVisionFlxGView {public static function releaseForSave(v:Dynamic):Void{}public function getField(f:String):Dynamic return null;public function setField(f:String,v:Dynamic):Dynamic return v;}'
  files['PsychBaseStageActorGroupCompat.hx']='class PsychBaseStageActorGroupCompat {}'
  files['Character.hx']='class Character {public var animation:Dynamic;public var curCharacter="native";public var nightmareVisionHealthIcon:Null<String>;public var psychHealthIcon:Null<String>;var sourceHealthIconAssigned=false;var sourceHealthIconValue:String;public var healthIcon(get,set):String;public function new(){}'+methods+'}'
  files['Main.hx']=r'''class Main {static function ok(v:Bool,m:String)if(!v)throw m;static function main(){var files:Map<String,String>=["owner/characters/costume.json"=>'{"healthicon":"logical-pixel"}',"other/characters/costume.json"=>'{"healthicon":"other-icon"}'];var c=new Character();c.curCharacter="costume";c.psychHealthIcon=PsychCharacterHealthIcon.authored("costume","owner",p->files.get(p));ok(c.healthIcon=="logical-pixel","source JSONhealthicon differscharacterid");var bridge=new SourceIrisBridge({});bridge.variables.set("actor",c);bridge.evaluate("actor.healthIcon='script-icon'; readback=actor.healthIcon;", "character-icon.hx");ok(c.healthIcon=="script-icon"&&bridge.variables.get("readback")=="script-icon","actualIris publicfield write/read");Reflect.setProperty(c,"healthIcon","lua-icon");ok(c.healthIcon=="lua-icon","nativeproperty setter");@:privateAccess c.sourceHealthIconAssigned=false;c.psychHealthIcon=PsychCharacterHealthIcon.authored("costume","other",p->files.get(p));ok(c.healthIcon=="other-icon","character reload changesownerlogicalid");c.nightmareVisionHealthIcon="nv-id";ok(c.healthIcon=="nv-id","NVmetadata precedence");c.healthIcon="new-nv-id";ok(c.healthIcon=="new-nv-id","NVsource writablefield");var n=new Character();ok(n.healthIcon=="native","nativeidentifier fallback retained");ok(PsychCharacterHealthIcon.authored("../bad","owner",p->throw "unsafe read")==null,"pathscopeguard");}}'''
  self.run_haxe(files)
  self.assertIn('psychHealthIcon = sourceCharacterOwnerEngine.toLowerCase() == ImportEngine.PSYCH.toLowerCase()',char)
  self.assertIn('sourceHealthIconAssigned = false;',char)


